from docx import Document
from docx.shared import Pt
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
p='/work/complaint_preparation.docx'
d=Document(p)
def apply(run, family, size=None, bold=None):
    run.font.name=family
    if size is not None: run.font.size=Pt(size)
    if bold is not None: run.bold=bold
    rp=run._element.get_or_add_rPr()
    rf=rp.rFonts
    if rf is None:
        rf=OxmlElement('w:rFonts'); rp.insert(0,rf)
    for a in ('ascii','hAnsi','eastAsia','cs'): rf.set(qn('w:'+a),family)
for para in d.paragraphs:
    if para.text.strip() == '民事起诉状':
        for r in para.runs: apply(r,'SimHei',18,True)
        para.paragraph_format.keep_with_next=True
for style_name,size in [('Title',20),('Heading 1',16),('Heading 2',13),('Heading 3',12)]:
    s=d.styles[style_name]
    s.font.name='SimHei'; s.font.size=Pt(size); s.font.bold=True
    rp=s._element.get_or_add_rPr(); rf=rp.rFonts
    if rf is None: rf=OxmlElement('w:rFonts'); rp.insert(0,rf)
    for a in ('ascii','hAnsi','eastAsia','cs'): rf.set(qn('w:'+a),'SimHei')
d.save(p)
print('restored manual legal-document title font')
